 function teamValue(r,key,fallback){if(Number.isFinite(r.details[key]))return r.details[key];const values=DB.profiles.filter(p=>r.details.teamIds?.includes(p.id)).map(p=>p.results.find(v=>v.game==='air'&&v.details?.matchId===r.details.matchId)?.details?.[fallback]||0);return key==='teamFruit'?values.reduce((a,b)=>a+b,0):Math.max(0,...values);}
