   if(phase==='countdown'){if(config.input==='camera'&&!trackingHealthy()){if(world)trackingPause('Arms left the view before the countdown finished.');else calibrationScreen(false);}else{const left=Math.min(3,Math.ceil((countdownEnd-now)/1000));if(left>0&&left!==lastCount){lastCount=left;q('#airCountdown').textContent=left;sound.fx('tick');}if(left<=0){phase='play';q('#airOverlay').hidden=true;poorTrackingSince=0;motion.reset();pointer?.clear();sound.fx('go');sound.playMusic();last=now;dt=0;}}}
